#include "ModeManager_ModeManager.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void ModeManager_ModeManager_initialize(void);
void ModeManager_ModeManager_notify(microkit_channel channel);
void ModeManager_ModeManager_timeTriggered(void);

volatile sb_queue_SW_AttackStatus_1_t *AttackStatusRx_queue_1;
sb_queue_SW_AttackStatus_1_Recv_t AttackStatusRx_recv_queue;
volatile sb_queue_SW_AttackStatus_1_t *AttackStatusTx_queue_1;
sb_queue_SW_AttackStatus_1_Recv_t AttackStatusTx_recv_queue;
volatile sb_queue_SW_Mode_1_t *CurrentMode_queue_1;

#define PORT_FROM_MON 0

SW_AttackStatus last_AttackStatusRx_payload;

bool get_AttackStatusRx(SW_AttackStatus *data) {
  sb_event_counter_t numDropped;
  SW_AttackStatus fresh_data;
  bool isFresh = sb_queue_SW_AttackStatus_1_dequeue((sb_queue_SW_AttackStatus_1_Recv_t *) &AttackStatusRx_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_AttackStatusRx_payload = fresh_data;
  }
  *data = last_AttackStatusRx_payload;
  return isFresh;
}

uintmax_t get_AttackStatusRx_num_invalid(void) {
  return sb_queue_SW_AttackStatus_1_numInvalid((sb_queue_SW_AttackStatus_1_Recv_t *) &AttackStatusRx_recv_queue);
}

SW_AttackStatus last_AttackStatusTx_payload;

bool get_AttackStatusTx(SW_AttackStatus *data) {
  sb_event_counter_t numDropped;
  SW_AttackStatus fresh_data;
  bool isFresh = sb_queue_SW_AttackStatus_1_dequeue((sb_queue_SW_AttackStatus_1_Recv_t *) &AttackStatusTx_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_AttackStatusTx_payload = fresh_data;
  }
  *data = last_AttackStatusTx_payload;
  return isFresh;
}

uintmax_t get_AttackStatusTx_num_invalid(void) {
  return sb_queue_SW_AttackStatus_1_numInvalid((sb_queue_SW_AttackStatus_1_Recv_t *) &AttackStatusTx_recv_queue);
}

bool put_CurrentMode(const SW_Mode *data) {
  sb_queue_SW_Mode_1_enqueue((sb_queue_SW_Mode_1_t *) CurrentMode_queue_1, (SW_Mode *) data);

  return true;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_SW_AttackStatus_1_Recv_init(&AttackStatusRx_recv_queue, (sb_queue_SW_AttackStatus_1_t *) AttackStatusRx_queue_1);

  sb_queue_SW_AttackStatus_1_Recv_init(&AttackStatusTx_recv_queue, (sb_queue_SW_AttackStatus_1_t *) AttackStatusTx_queue_1);

  sb_queue_SW_Mode_1_init((sb_queue_SW_Mode_1_t *) CurrentMode_queue_1);

  ModeManager_ModeManager_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      ModeManager_ModeManager_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      ModeManager_ModeManager_notify(channel);
  }
}
